beforeExample:
public class Example {
    public void method() {
        java.lang.StringBuffer buf = new java.lang.StringBuffer("test");
        buf.append("ing");
        System.out.println(buf.toString());
    }

    public void anotherMethod() {
        java.lang.StringBuffer anotherBuf = new java.lang.StringBuffer(10);
        anotherBuf.append('c');
    }

    public void multipleAppends() {
        java.lang.StringBuffer tempBuffer = new java.lang.StringBuffer();
        tempBuffer.append("Hello").append(" ").append("World");
    }
}

afterExample:
public class Example {
    public void method() {
        java.lang.StringBuilder buf = new java.lang.StringBuilder("test");
        buf.append("ing");
        System.out.println(buf.toString());
