public class NegativeExample {
    private java.lang.StringBuffer sharedBuffer = new java.lang.StringBuffer("shared"); // Should not change (field)

    public void modifySharedBuffer(java.lang.StringBuffer paramBuffer) { // Parameter, should not change
        paramBuffer.append(" modified");
    }

    public static java.lang.StringBuffer createAndReturnBuffer() { // Return value, should not change
        return new java.lang.StringBuffer("returned");
    }

    public void testMethod() {
        java.lang.StringBuffer localButNotDeclaredWithInitializer = null;
        localButNotDeclaredWithInitializer = new java.lang.StringBuffer("assign"); // Not direct initializer
    }
}
